mapper.select:
SELECT COALESCE(SUM(
    CASE WHEN ended_at IS NULL THEN reserved_seconds ELSE wall_duration_seconds END
), 0)
FROM voice_practice_session
WHERE started_at >= #{from}
  AND started_at < #{to}

    AND user_id = #{userId}

mapper.update:
UPDATE voice_practice_session
SET ended_at = #{endedAt},
    wall_duration_seconds = #{wallDurationSeconds},
    stopped_by_cap = #{stoppedByCap}
WHERE id = #{id}

UPDATE voice_practice_session
SET transcript = #{transcript},
    transcript_saved = 1,
    stopped_by_cap = #{stoppedByCap}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.select:
SELECT 
FROM voice_practice_session
WHERE user_id = #{userId}
  AND transcript_saved = 1
ORDER BY started_at DESC
LIMIT #{limit}
